function MDCleanVal(v) {
  var s = String(v == null ? '' : v).replace(/^\s+|\s+$/g, '');
  if (!s) return '';
  if (s.indexOf('[object') === 0) return '';
  for (var i = 0; i < MD_BAD_WORDS.length; i++) {
    if (s === MD_BAD_WORDS[i]) return '';
  }
  return s;
}

function MDCollectAllTexts() {
  var out = [];

  function safe(fn, def) {
    try {
      var r = fn();
      if (r === undefined || r === null) return def;
      return r;
    } catch (e) { return def; }
  }

  function nameOf(v) {
    return safe(function () { return String(v.getClass().getName()); }, '');
  }

  function textOf(v) {
    return safe(function () { return String(v.getText().toString()); }, '');
  }

  function scan(v, depth) {
    if (!v || depth > 40 || out.length >= 16) return;

    var cls = nameOf(v);
    if (cls.indexOf('EditText') >= 0) {
      var t = MDCleanVal(textOf(v));
      if (t && out.indexOf(t) < 0) out.push(t);
      return;
    }

    var n = safe(function () { return v.getChildCount(); }, 0);
    n = Number(n) || 0;
    for (var i = 0; i < n; i++) {
      var child = safe(function () { return v.getChildAt(i); }, null);
      scan(child, depth + 1);
    }
  }

  var act = safe(function () { return java.getActivity(); }, null);
  if (act) {
    var win = safe(function () { return act.getWindow(); }, null);
    if (win) {
      var dec = safe(function () { return win.getDecorView(); }, null);
      if (dec) scan(dec, 0);
    }
  }

  if (!out.length) {
    var ctx = safe(function () { return java.getContext(); }, null);
    if (ctx) {
      var win2 = safe(function () { return ctx.getWindow(); }, null);
      if (win2) {
        var dec2 = safe(function () { return win2.getDecorView(); }, null);
        if (dec2) scan(dec2, 0);
      }
    }
  }

  if (!out.length) {
    try {
      var AT = Packages.android.app.ActivityThread;
      var at = AT.currentActivityThread();
      var m = AT.getDeclaredMethod('getApplication', null);
      m.setAccessible(true);
      var app = m.invoke(at, null);
      if (app) {
        var win3 = safe(function () { return app.getWindow(); }, null);
        if (win3) scan(safe(function () { return win3.getDecorView(); }, null), 0);
      }
    } catch (e) {}
  }

  return out;
}



