function MDCredCandidates(holder) {
  var accs = [], pws = [];

  function pa(v) {
    v = MDCleanVal(v);
    if (v && accs.indexOf(v) < 0 && accs.length < 5) accs.push(v);
  }
  function pp(v) {
    v = MDCleanVal(v);
    if (v && pws.indexOf(v) < 0 && pws.length < 8) pws.push(v);
  }

  var rv = MDResultVals();
  if (rv.acc) pa(rv.acc);
  if (rv.pw) pp(rv.pw);

  var saved = MDLoadCreds(holder);
  pa(saved.acc);
  pp(saved.pw);

  var texts = MDCollectAllTexts();
  if (texts.length >= 2) {
    pa(texts[0]);
    for (var i = 1; i < texts.length; i++) pp(texts[i]);
  } else if (texts.length === 1) {
    pa(texts[0]);
