    'http://www.wuxie.qd.je',
    'https://wuxie.qd.je',
    'http://wuxie.qd.je',
    'https://www.wuxie.qd.je/',
    'wuxie.qd.je'
  ];

  function tryCM(getter) {
    for (var i = 0; i < hosts.length; i++) {
      try {
        var v = String(getter(hosts[i]) || '');
        if (v && v.indexOf('my_sid=') >= 0) return v;
      } catch (e) {}
    }
    return '';
  }

  try {
    var cm = android.webkit.CookieManager.getInstance();
    try { cm.flush(); } catch (e) {}
    ck = tryCM(function (h) { return cm.getCookie(h); });
  } catch (e) {}

  if (!ck) {
    try {
      var cm2 = Packages.android.webkit.CookieManager.getInstance();
      if (cm2 && cm2.flush) { try { cm2.flush(); } catch (e) {} }
      ck = tryCM(function (h) { return cm2.getCookie(h); });
    } catch (e) {}
  }

  if (!ck) {
    try {
      ck = tryCM(function (h) { return cookie.getCookie(h); });
    } catch (e) {}
  }

  if (!ck) return '';

  var m = ck.match(/(?:^|;\s*)my_sid=([^;]+)/);
  if (!m) return '';
  var v = m[1];
  try { v = decodeURIComponent(v); } catch (e) {}
  return String(v).replace(/^\s+|\s+$/g, '');
}





