/* ===== 夜社多模式工具（jsLib 纯函数，java/source/book 一律显式传参） ===== */
var YS_NL=String.fromCharCode(10), YS_Q=String.fromCharCode(34), YS_BS=String.fromCharCode(92,47);
function YS_DEF(){return 'https://xn--a3sy5k4mjdhu-jm5tm10qooyeogza.taobaoyoumaia.com:7982'}
function YS_get(S,k,d){var v='';try{v=String(S.get(k)||'')}catch(e){}if(!v||v=='null'||v=='undefined')v=d;return v}
function YS_line(S){return YS_get(S,'ys_line',YS_DEF())}
function YS_pick(S){return YS_line(S)}
function YS_mode(S){
  var a='';try{a=S.getVariable()}catch(e){}
  a=String(a==null?'':a);
  if(a==='null'||a==='undefined'||a===''){try{a=String(S.get('ys_mode')||'')}catch(e2){}}
  if(a==='null'||a==='undefined'||a==='')a='小说';
  return a;
}
/* 形态：text/video/audio/image */
function YS_shape(m){
  if(m==='小说')return 'text';
  if(m==='漫画'||m==='写真')return 'image';
  if(m==='有声')return 'audio';
  return 'video';
}
/* 响应解码：<script>var a="BASE64"</script> */
function YS_dec(J,r){
  var s=String(r==null?'':r);
  try{var k=s.indexOf('var a=');if(k>=0){var q=s.indexOf(YS_Q,k+6),q2=s.indexOf(YS_Q,q+1);if(q>0&&q2>q){var b=s.substring(q+1,q2);if(b.length>100)return String(J.base64Decode(b))}}}catch(e){}
  return s;
}
function YS_doc(J,r){return Packages.org.jsoup.Jsoup.parse(YS_dec(J,r))}
function YS_txt(J,r,sel){try{var e=YS_doc(J,r).select(sel);return e.size()>0?String(e.get(0).text()):''}catch(e){return ''}}
function YS_attr(J,r,sel,attr){try{var e=YS_doc(J,r).select(sel);return e.size()>0?String(e.get(0).attr(attr)||''):''}catch(e){return ''}}
function YS_LIST(a){var l=new Packages.java.util.ArrayList();if(!a)return l;for(var i=0;i<a.length;i++)l.add(typeof a[i]==='string'?a[i]:JSON.stringify(a[i]));return l;}
function YS_listJson(J,r,sel){
  var arr=[];
  try{
    var els=YS_doc(J,r).select(sel);
    for(var i=0;i<els.size();i++){
      var a=els.get(i),ims=a.select('img'),cov='';
      if(ims.size()>0){cov=String(ims.get(0).attr('data-original')||'');if(!cov)cov=String(ims.get(0).attr('src')||'');}
      arr.push({name:String(a.select('div.module-poster-item-title').text()||''),
        bookUrl:String(a.attr('href')||''),kind:String(a.select('div.type').text()||''),
        cover:cov,wordCount:String(a.select('span.time').text()||'')});
    }
  }catch(e){}
  return YS_LIST(arr);
}
function YS_noParen(t){var x=String(t==null?'':t),i=x.indexOf('(');return (i>0?x.substring(0,i):x).trim()}
function YS_player(J,r){
  var s=YS_dec(J,r),p=s.indexOf('player_aaaa');
  if(p<0)return null;
  var st=s.indexOf('{',p),dep=0,en=st;
  for(var k=st;k<s.length&&k<st+6000;k++){var c=s.charAt(k);if(c=='{')dep++;else if(c=='}'){dep--;if(dep===0){en=k+1;break;}}}
  if(en<=st)return null;
  try{return JSON.parse(s.substring(st,en))}catch(e){return null}
}
/* 媒体直链：video/audio 正文返回纯 URL（交给 ExoPlayer/音频播放器） */
function YS_mediaUrl(J,r){
  var p=YS_player(J,r);
