function YS_speed(){
  YS_T('⏳ 测速 8 条线路中，约 10~30 秒...');
  var hosts=YS_get('ys_hosts','').split(',');if(!hosts.length||!hosts[0])hosts=YS_DOMAINS.slice(0);
  var urls=[];for(var i=0;i<hosts.length;i++)urls.push('https://'+hosts[i]+':'+YS_PORTS[0]+'/');
  var res=[];try{res=java.ajaxAll(urls)}catch(e){}
  var best=-1,bms=99999999,msgs=[];
  for(var k=0;k<hosts.length;k++){
    var ms='超时',ok=false,t=0;
    try{
      var r=res[k],body=String(r.body());
      try{t=r.getCallTime()}catch(e1){try{t=Number(r.callTime())}catch(e2){}}  // ★修复：getCallTime()
      if(body.length>20000){ok=true;ms=t+'ms';if(t>0&&t<bms){bms=t;best=k;}}
    }catch(e3){}
    try{source.put('yssp'+(k+1),ok?ms:'超时')}catch(e4){}
    msgs.push((k+1)+'.'+hosts[k].substring(0,10)+' '+ms);
  }
  if(best>=0){var cur='https://'+hosts[best]+':'+YS_PORTS[0];YS_save(cur);try{source.put('yssp'+(best+1),'⚡'+(bms+'ms'))}catch(e5){}YS_T('✅ 最快'+(best+1)+'号 '+bms+'ms 已自动切换');}
