// 通道 A：直接 POST（出口没被 CF 挡时最快）
function EH_tryPost(c) {
  var body = 'referer=https://forums.e-hentai.org/index.php?&b=&bt=&UserName=' +
             encodeURIComponent(c.u) + '&PassWord=' + encodeURIComponent(c.p) + '&CookieDate=1';
  var opt = '{"method":"POST","body":' + JSON.stringify(body) +
            ',"headers":{"User-Agent":' + JSON.stringify(EH_UA) +
            ',"Content-Type":"application/x-www-form-urlencoded"' +
            ',"Referer":"https://forums.e-hentai.org/index.php?act=Login&CODE=00"}}';
  var r, b = '';
  try {
    r = java.connect(EH_LOGIN_POST + ',' + opt, '', 20000);
    b = String(r.body());
  } catch (e) { return { ok: false, reason: 'POST异常 ' + String(e).slice(0, 50) }; }
  if (/Just a moment|cf-mitigated|challenge|Checking your browser/i.test(b)) {
    return { ok: false, reason: 'Cloudflare 挑战页（需内置浏览器过盾）' };
  }
  if (/You are now logged in as|Logged in as|logout|Log Out/i.test(b)) {
    // 从响应头 Set-Cookie 或 CookieStore 取
    var raw = '';
    try { raw = String(r.headers()); } catch (e) {}
    if (!raw) { try { raw = String(cookie.getCookie('https://forums.e-hentai.org/')); } catch (e2) {} }
    var k = EH_extract2(raw);
    if (!k.ipb_member_id) { try { k = EH_extract2(cookie.getCookie('https://forums.e-hentai.org/')); } catch (e3) {} }
    if (k.ipb_member_id && k.ipb_pass_hash) return { ok: true, keep: k };
    return { ok: false, reason: '登录成功但未读到 Cookie（检查 CookieJar）' };
  }
  return { ok: false, reason: '账号密码错误 / 需验证码 / 未识别响应（' + b.length + 'B）' };
}
// 通道 B：内置浏览器（过 CF + 手动登录，用户填完点页面里的登录即可）
function EH_browserLogin() {
  EH_toast('🌐 正在打开论坛登录页…请在内置浏览器里完成 Cloudflare 验证并登录账号，登录后返回本面板再点「🔄 读取登录 Cookie」');
  try {
