//   不因「超清档」把并发拉到 60 张；首屏之外的图一律交给 WebView 视口懒加载。
var EH_RES = [
  { k: '0', n: '省流·缩略图≈250px', hd: 0,  gap: 1000, margin: '0px',    xr: '1', ts: '0' },
