  { k: '2', n: '高清·1280x(WiFi)',   hd: 15, gap: 450,  margin: '1200px', xr: '3', ts: '2' },
  { k: '3', n: '超清·全量·大屏',     hd: 25, gap: 350,  margin: '1800px', xr: '3', ts: '2' }
];
function EH_resCfg() {
  // 主存档 ehRes（由 select 的 EH_setRes 写入）；
  // 兼容：若面板 select 已选但 action 未触发，可从 result/infoMap 的标签反查档位。
  // ★261114 v5.3b：整个函数体包 try/catch —— 本函数在 viewName 求值环境里被
  //   EH_resStatus/EH_status 调用，任何一步异常都会让整个求值串变空 → 按钮显示 "null"。
  try {
    var k = EH_gv('ehRes', '1');
    var label = '';
    try { if (typeof result !== 'undefined' && result != null) {
            if (typeof result.get === 'function') { try { label = String(result.get('ehResSelect') || ''); } catch (e00) {} }
            if (!label) { try { label = String(result['ehResSelect'] || ''); } catch (e01) {} }
          } } catch (e0) {}
    if (!label) { try { if (typeof infoMap !== 'undefined' && infoMap) label = String(infoMap['ehResSelect'] || ''); } catch (e1) {} }
    if (label) {
      for (var i = 0; i < EH_RES.length; i++) {
        if (label.indexOf(EH_RES[i].n) >= 0) { k = EH_RES[i].k; break; }
      }
    }
    for (var j = 0; j < EH_RES.length; j++) if (EH_RES[j].k === k) return EH_RES[j];
    return EH_RES[1];
  } catch (eBig) { return EH_RES[1]; }
}
