    var ms = EH_gv(Number(n) === 1 ? 'ehPingEx' : 'ehPingTable', '');
    var cur = (EH_host().indexOf(Number(n) === 1 ? 'exhentai' : 'e-hentai') >= 0) ? '【当前】' : '';
    return ("'" + cur + d + (ms !== '' && ms !== '-1' ? ' · ' + ms + 'ms' : ' · 未测速') + "（点击切换）'") || "'切换线路'";

  } catch (eVN) { return "'切换线路'"; }
}
function EH_switchHostEx(n) {
  EH_toast('🔀 正在切换线路到 ' + (Number(n) === 1 ? '里站 exhentai.org' : '表站 e-hentai.org') + '…');
  EH_switchHost(n);   // 复用原函数（内含 Toast + refresh）
  EH_toast('ℹ 切换完成。★重新进入订阅/发现页生效；建议点「⚡ 测试各线路延时」复核新线路');
}

// ---- ③ 明确的「检查登录状态」按钮（须登录站点要求）----
function EH_checkLogin() {
  var d = EH_host();
  EH_toast('✅ 正在检查登录状态：请求 ' + d + ' 首页（单次，不触发搜索）…');
  var body = '';
  try { body = String(java.ajax(EH_ajaxUrl('/'))); }
  catch (e) { EH_toast('❌ 请求异常：' + String(e).slice(0, 80) + ' ⇒ 检查 VPN/代理'); return; }
  if (/Exception|timeout|Failed to connect|SSLHandshake/i.test(body.slice(0, 200))) {
    EH_toast('❌ 网络不通（DNS 污染 / SNI 封锁 / 代理未生效）⇒ 填代理或换 VPN 节点'); return;
  }
  if (/temporarily banned|excessive request|Your IP address has been/i.test(body)) {
    EH_toast('❌ 出口 IP 被站方限频（约 24h 解封）⇒ 换 VPN 节点，勿频繁刷新'); return;
  }
  if (body.length < 1000) {
    EH_toast('❌ 空白页（' + body.length + 'B）⇒ 先在上方粘贴【你自己账号】的完整 Cookie 并点「💾 保存 Cookie」；再点「🔄 刷新 igneous」。★本源不再内置任何测试账号'); return;
  }
  if (/Sad Panda|sadpanda|You do not have access/i.test(body)) {
    EH_toast('❌ Sad Panda（账号无里站权限）⇒ 需已审核的 E-Hentai 账号 Cookie'); return;
  }
  var g = (body.match(/\/g\/\d+\/[0-9a-f]{10}\//g) || []).length;
  var logged = /ipb_member_id|logged in|Log Out|logout|My Home|Hath Perks/i.test(body);
  EH_toast('✅ 已登录且可用：' + body.length + 'B 首页 / ' + g + ' 个画廊' +
           (logged ? ' / 页面含登录态标识' : '') + '。★可正常浏览；分辨率档位=' + EH_resCfg().n);
}
// ---- ⑧ 发布页输入框 → 一键取线路（E-Hentai 无官方「网址发布页」，明确降级不臆造） ----
function EH_fromPub() {
  EH_toast('🔗 正在读取「发布页网址输入框」…');
  var u = EH_input('ehPubInput').trim();
  if (!u) {
    EH_toast('ℹ 输入框为空：E-Hentai / ExHentai 官方没有「网址发布页」，只有表站/里站两条固定线路；已为你改用下方两条，并开始测速…');
    EH_testDelay();
    return;
  }
  if (!/^https?:\/\//i.test(u)) u = 'https://' + u;
  EH_toast('🔗 读到自定义线路：' + u + '，正在测速（单次，不频繁访问）…');
  var r = EH_pingOne(u.replace(/\/+$/, ''));
  if (r.ms >= 0 && r.len > 1000) {
    EH_set('ehHost', u.replace(/\/+$/, ''));
    EH_set('ehPingText', '自定义 ' + r.ms + 'ms');
    EH_toast('✅ 自定义线路可用：' + r.ms + 'ms / ' + r.len + 'B，已切换为当前站点；请重新进入订阅页');
  } else {
    EH_toast('❌ 自定义线路不可用（' + (r.ms >= 0 ? r.ms + 'ms / ' + r.len + 'B' : '超时') +
             '）⇒ 未切换，仍用当前线路；可点「⚡ 测试各线路延时」核对表/里站');
  }
  EH_refresh();
}


// ==================== 📁 正文显示收藏夹（261113 v4 新增） ====================
// 开关存 ehFavPanel（'1'=正文信息下方显示收藏夹列表 / '0'=不显示）。
// 正文 ruleContent 读该变量：开启时才请求 1 次 favorites.php 抓夹名单，
// 渲染 10 个夹子 chip；点击 chip 页内直接 POST gallerypopups.php addfav
// （加入/移出即时生效，不重载正文、不失效缓存）。
function EH_favToggle() {
  var cur = EH_gv('ehFavPanel', '0');
  var nw = (cur === '1') ? '0' : '1';
  EH_set('ehFavPanel', nw);
  EH_toast(nw === '1'
    ? '📁 已开启：正文信息下方将显示你的收藏夹列表（点击夹子加入/再点移出当前画廊）。★已打开的文章有正文缓存，退出重进生效'
    : '📁 已关闭：正文不再显示收藏夹列表。★已打开的文章退出重进生效');
  EH_refresh();
}
function EH_favBtn() {
  try {

    var on = EH_gv('ehFavPanel', '0') === '1';
    return ("'📁 正文显示收藏夹：" + (on ? '开（点击关闭）' : '关（点击开启）') + "'") || "'📁 正文显示收藏夹'";

  } catch (eVN) { return "'📁 正文显示收藏夹'"; }
}


// ==================== 🏷 tag 点击模式（261114 v5 新增） ====================
// 两个独立开关：ehTagSearch（点 tag 名字搜索对应 tag）/ ehTagWatch（点 ＋/✓ 订阅对应 tag）。
// 可组合：都开时名字可点搜索、旁边独立 chip 订阅，互不抢点击。
// 订阅协议实锤：POST /mytags add(tagwatch_new=on) / mass(modify_usertags[]=id) 取消；
// 两者都返回 302，成功判据=回读 /mytags 出现/消失（沙盒真机闭环）。
function EH_tagToggle(k) {
  var nw = (EH_gv(k, '0') === '1') ? '0' : '1';
  EH_set(k, nw);
  var n = (k === 'ehTagSearch') ? '点 tag 搜索' : '订阅 tag';
  EH_toast('🏷 ' + n + '：' + (nw === '1' ? '已开启' : '已关闭') +
           '。★已打开的文章有正文缓存，退出重进生效');
  EH_refresh();
}
function EH_tagBtn(k, name) {
  try {

    var on = EH_gv(k, '0') === '1';
    return ("'🏷 " + name + "：" + (on ? '开（点击关闭）' : '关（点击开启）') + "'") || "'🏷 tag 开关'";

  } catch (eVN) { return "'🏷 tag 开关'"; }
}


// ==================== 🔄 刷新 igneous（261114 v5.1 登录态持久化） ====================
// 站方对「只发两项」的请求会 Set-Cookie 一个 30 天有效 igneous（同账号重签同值）。
// enabledCookieJar=false 后不再自动回存，故这里用 java.connect（返回 StrResponse，
// 有 headers()）抓 Set-Cookie 存进源变量 ehIgneous；header/loginCheckJs/正文四处统一读它。
// ★ 绝不存 'mystery'（站方 Sad Panda 页下发的失效值，带上就 0B 白屏）。
function EH_refreshIgneous() {
  EH_toast('🔄 正在请求里站首页，读取站方签发的有效 igneous…');
  var u = EH_host() + '/,{"headers":' + JSON.stringify({
    'User-Agent': EH_UA,
    'Cookie': EH_cookie(EH_gv('ehCookie', '')),
    'Referer': 'https://exhentai.org/'
  }) + '}';
  var hdr = '', body = '';
  try {
    var r = java.connect(u, '', 20000);
    try { hdr = String(r.headers()); } catch (e1) { hdr = ''; }
    try { body = String(r.body()); } catch (e2) { body = ''; }
  } catch (e) { EH_toast('❌ 请求异常：' + String(e).slice(0, 90) + ' ⇒ 检查代理/VPN'); return; }
  var m = /igneous=([A-Za-z0-9]{6,40})/.exec(hdr);
  if (m && m[1] !== 'mystery') {
    EH_set('ehIgneous', m[1]);
    EH_toast('✅ 已保存有效 igneous=' + m[1] + '（30天有效）。以后打开订阅源无需再清 Cookie 重登；退出重进文章生效');
  } else if (body.length > 5000) {
    // 站方这次没重签（说明请求里已带有效 igneous）→ 沿用当前值即可
    var cur = EH_gv('ehIgneous', '');
    EH_toast('✅ 首页正常（' + body.length + 'B）；站方这次未重签 igneous' +
             (cur ? '，当前值 ' + cur.slice(0, 8) + '… 仍有效' : '，用空值占位即可，站方按需重签') + '，无需刷新');
  } else {
    EH_toast('⚠ 未读到有效 igneous（首页 ' + body.length + 'B）⇒ 点「🩺 一键自愈」后重试，或粘贴浏览器完整 Cookie');
  }
  EH_refresh();
}
function EH_igBtn() {
  try {

    var ig = EH_gv('ehIgneous', '');
    return ("'🔄 刷新 igneous（当前 " + (ig ? ig.slice(0, 8) + '…' : '空值占位·站方自动重签') + "）'") || "'🔄 刷新 igneous'";

  } catch (eVN) { return "'🔄 刷新 igneous'"; }
}


// ==================== 🩺 登录态一键诊断（261114 v5.2） ====================
// 用户报「收藏夹获取失败 / 订阅tag失败：检查登录状态 / 关注列表为空」时的定位按钮：
// 分别打 /watched /favorites.php /mytags，回报每页大小与站方提示，区分
// 「没配Cookie」/「igneous 无效」/「该账号确实没有 watched tag」三种情况。
function EH_diagLogin() {
  var ck = EH_gv('ehCookie', '');
  if (ck.indexOf('ipb_member_id=') < 0 || ck.indexOf('ipb_pass_hash=') < 0) {
    EH_toast('❌ 未检测到你自己的 Cookie ⇒ 请在面板「① 里站 Cookie」粘贴浏览器登录后复制的完整串并点「💾 保存 Cookie」。★本源不内置任何账号');
    return;
  }
  var ig = EH_gv('ehIgneous', '');
  EH_toast('🩺 正在诊断：Cookie 已配置（member=' + (/ipb_member_id=(\d+)/.exec(ck) || [])[1] +
           '），igneous=' + (ig ? ig.slice(0, 8) + '…' : '空值占位') + '；依次请求 watched/favorites/mytags…');
  var paths = ['/watched', '/favorites.php', '/mytags'], res = [], i;
  for (i = 0; i < paths.length; i++) {
    var b = '';
    try { b = String(java.ajax(EH_ajaxUrl(paths[i]))); } catch (e) { b = String(e); }
    var tag = /Exception|timeout|Failed to connect/i.test(b.slice(0, 200)) ? '网络异常' :
              /temporarily banned|excessive request/i.test(b) ? 'IP限频' :
              b.length < 1000 ? '空白页(登录态无效)' :
              /You do not have any watched tags/i.test(b) ? '该账号确实没有 watched tag' :
              /No hits found/i.test(b) ? '页内无结果' : '正常(' + b.length + 'B)';
    res.push(paths[i] + '→' + tag);
    if (i < paths.length - 1) { try { Packages.java.lang.Thread.sleep(400); } catch (eS) {} }
  }
  EH_toast('🩺 诊断结果：' + res.join(' / ') +
           '。★若 watched 报「没有 watched tag」= 订阅没成功，请先在正文点 tag 旁的 ＋ 订阅，或到站内 My Tags 添加');
}
function EH_diagBtn() {
  return "'🩺 登录态一键诊断（区分没配Cookie/igneous无效/无watched标签）'" || "'🩺 登录态一键诊断'";
}

