@js:(function(){var _html=
(function () {
  // ============================================================
  // ExHentai 订阅源 · 正文规则（画廊详情页 → 自拼纯净 HTML）
  // 数据源 = result（App 已按 header.js 的 proxy/Cookie 抓好的内容页 HTML 字符串）
  // 结构依据：Venera ehentai.js / H-Viewer 规则 / TachiyomiSY / RSSHub 源码 +
  //           Keenable 实时页面文本（2026-11-07 交叉实锤）
  // ★ 不写死页码上限：后续缩略图页数完全由站点 #gdd 的 "N pages" 与
  //   table.ptb 的最大 ?p=N 推导，站点以后加页会自动跟着变。
  // ============================================================
  var NL = String.fromCharCode(10);
  var raw = '';
  try { raw = (result && result.html) ? String(result.html()) : String(result); } catch (e) { raw = String(result); }
  var pageUrl = String(baseUrl);

  function esc(s) {
    return String(s == null ? '' : s)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
  }
  function stripTags(s) {
    return String(s == null ? '' : s).replace(/<[^>]*>/g, '')
      .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'")
      .replace(/\s+/g, ' ').trim();
  }
  function pick(re, def) { var m = re.exec(raw); return m ? stripTags(m[1]) : (def || ''); }
  function gv(k, def) {
    var v = '';
    try { v = String(source.get(k)); } catch (e) { v = ''; }
    if (v === 'null' || v === 'undefined' || v === 'NaN' || v === '') v = def || '';
    return v;
  }
  // ---- 0. 诊断闸门：把三类伪装错误页直接变成可读提示（WS 调试据此定位） ----
  if (!raw || raw.length < 500) {
    return '<div style="padding:18px;color:#c33;line-height:1.8">' +
      '<h3>⚠ 内容页为空（' + raw.length + 'B）</h3>' +
      '典型原因：<b>Sad Panda 登录墙（空白页）</b> / 里站 Cookie 无效。<br>' +
      '请到登录面板粘贴含 <code>igneous</code> 的 Cookie，并配置可访问里站的代理。' +
      '<p><a href="' + esc(pageUrl) + '">打开原页面</a></p></div>';
  }
  if (/temporarily banned|excessive request rate|Your IP address has been banned/i.test(raw)) {
    return '<div style="padding:18px;color:#c33;line-height:1.8"><h3>⚠ 出口 IP 被站方限频</h3>' +
      'E-Hentai 对自动抓取很敏感（通常封 24h）。请换代理出口或稍后再试，勿频繁刷新。' +
      '<p><a href="' + esc(pageUrl) + '">打开原页面</a></p></div>';
  }
  if (/Sad Panda|sadpanda|You do not have access|back to the E-Hentai Galleries/i.test(raw)) {
    return '<div style="padding:18px;color:#c33;line-height:1.8"><h3>⚠ Sad Panda（未登录里站）</h3>' +
      'ExHentai 需要 <code>ipb_member_id / ipb_pass_hash / igneous</code> 三项 Cookie。' +
      '请到登录面板粘贴浏览器里已登录的完整 Cookie。</div>';
  }
  if (raw.indexOf('id="gdt"') < 0 && raw.indexOf('class="itg') < 0) {
    return '<div style="padding:18px;color:#c33;line-height:1.8"><h3>⚠ 不是画廊详情页（' + raw.length + 'B）</h3>' +
      '抓到的页面里没有 <code>#gdt</code> 缩略图容器，可能是重定向到论坛登录页或 Cloudflare 挑战页。' +
      '<p><a href="' + esc(pageUrl) + '">打开原页面</a></p></div>';
  }

  // ---- 1. 元数据（全部纯字符串正则，跨 LT/E 两版 Rhino 无 jsoup 依赖） ----
  var title    = pick(/<h1[^>]*id=["']gn["'][^>]*>([\s\S]*?)<\/h1>/i, '');
  var titleJp  = pick(/<h1[^>]*id=["']gj["'][^>]*>([\s\S]*?)<\/h1>/i, '');
  var category = pick(/<div[^>]*class=["'][^"']*\bcs\b[^"']*["'][^>]*>([\s\S]*?)<\/div>/i, '');
  var uploader = pick(/<div[^>]*id=["']gdn["'][^>]*>([\s\S]*?)<\/div>/i, '');
  var rating   = pick(/<[^>]*id=["']rating_label["'][^>]*>([\s\S]*?)<\/[^>]+>/i, '');
  var favCount = pick(/<[^>]*id=["']favcount["'][^>]*>([\s\S]*?)<\/[^>]+>/i, '');
  // ---- 1.5 收藏夹：画廊身份(gid/token) + 当前收藏态（261113 真实页面结构实锤）----
  // 已收藏态：<div id="gdf"> 内 <a id="favoritelink">夹名</a>；未收藏=文本 "Add to Favorites"
  // 辅助判据：id="fav" 图标 div 的 title="夹名"（未收藏时 fav div 为空、无 title）
  var favGid = '', favTok = '';
  var gm = /\/g\/(\d+)\/([0-9a-f]{10})\//.exec(pageUrl);
  if (gm) { favGid = gm[1]; favTok = gm[2]; }
  var favCur = -1;          // 当前所在收藏夹索引（-1=未收藏；由夹名映射得出）
  var favCurName = '';      // 当前所在收藏夹名（favoritelink 文本）
  var gdfSeg = '';
  var gdfAt = raw.indexOf('id="gdf"');
  if (gdfAt >= 0) gdfSeg = raw.substring(gdfAt, gdfAt + 900);
  var flm = /<a[^>]*id=["']favoritelink["'][^>]*>([\s\S]*?)<\/a>/.exec(gdfSeg);
  if (flm) {
    var flTxt = stripTags(flm[1]);
    if (flTxt && !/Add to Favorites/i.test(flTxt)) favCurName = flTxt;
  }
  if (!favCurName) {
    var ftm = /id=["']fav["'][^>]*>[\s\S]{0,260}?title="([^"]*)"/.exec(gdfSeg);
    if (ftm) favCurName = stripTags(ftm[1]);
  }

  // 封面：#gd1 区块到 </div>，内部 style 里的 url(...)；再兜底全页第一张 ehgt 图
  var coverBig = '';
  var gd1 = /<div[^>]*id=["']gd1["'][^>]*>([\s\S]*?)<\/div>/i.exec(raw);
  var cm = gd1 ? /url\((?:["']?)([^)"']+\.(?:jpg|jpeg|png|webp|gif))(?:["']?)\)/i.exec(gd1[1]) : null;
  if (!cm) cm = /url\((?:["']?)(https?:\/\/[^)"'\s]+\.(?:jpg|jpeg|png|webp|gif))(?:["']?)\)/i.exec(raw);
  if (cm) { coverBig = cm[1].trim(); }

  // #gdd 表格里 Posted / File Size / Length(N pages) / Favorited
  var posted = '', filesize = '', pagesTxt = '', filecount = 0;
  var gdd = /<div[^>]*id=["']gdd["'][^>]*>([\s\S]*?)<\/div>/i.exec(raw);
  var gdtHtml = gdd ? gdd[1] : raw;
  var rowRe = /<tr[^>]*>([\s\S]*?)<\/tr>/gi, row;
  while ((row = rowRe.exec(gdtHtml)) !== null) {
    var cells = [], cRe = /<td[^>]*>([\s\S]*?)<\/td>/gi, c;
    while ((c = cRe.exec(row[1])) !== null) cells.push(stripTags(c[1]));
    if (cells.length >= 2) {
      var k = cells[0].replace(/:$/, '').toLowerCase(), v = cells[1];
      if (k === 'posted') posted = v;
      else if (k === 'file size') filesize = v;
      else if (k === 'length') {
        pagesTxt = v;
        var fm = /(\d+)\s*pages?/i.exec(v); if (fm) filecount = Number(fm[1]);
      }
    }
  }
  // 站点有时把 Length 放在 td.gdt2 而不成行
  if (!filecount) { var fm2 = /(\d+)\s*pages?/i.exec(stripTags(gdtHtml)); if (fm2) filecount = Number(fm2[1]); }

  // 标签（#taglist 每个 tr：namespace + 若干 a）
  // ★261114 v5：本段只收集结构化 tagRows，不拼 HTML —— 开关(tagSearch/tagWatch)、
  //   watchMap、origin 都在更后面才就绪，提前引用会因 var 提升得到 undefined。
  //   真正渲染在 §3.7（3.6 抓完 mytags 之后）。
  var tagRows = [], tagHtml = '';
  var ts = raw.indexOf('id="taglist"');
  if (ts < 0) ts = raw.indexOf("id='taglist'");
  if (ts >= 0) {
    var te = raw.indexOf('id="gdt"', ts);
    if (te < 0) te = raw.indexOf('id="gd5"', ts);
    if (te < 0) te = Math.min(raw.length, ts + 20000);
    tagHtml = raw.substring(ts, te);
  }
  var trRe = /<tr[^>]*>([\s\S]*?)<\/tr>/gi, tr;
  while ((tr = trRe.exec(tagHtml)) !== null) {
    var tcs = [], tdRe = /<td[^>]*>([\s\S]*?)<\/td>/gi, td;
    while ((td = tdRe.exec(tr[1])) !== null) tcs.push(td[1]);
