    let saved = String(c.stv_host || '').trim();
    if (saved) return saved.replace(/\/+$/, '');
    return 'https://sangtacviet.com';
}

function setStvHost(host) {
    let list = getStvHosts();
    let target = String(host || '').replace(/\/+$/, '');
    if (list.indexOf(target) == -1) {
        return { ok: false, message: '未配置的STV线路：' + host };
    }
    setConfig.call(this, { stv_host: target });
    return { ok: true, host: target };
}

function stvNextHost() {
    let list = getStvHosts();
    let cur = getStvHost.call(this);
    let idx = list.indexOf(cur);
    let next = list[(idx + 1) % list.length];
    setConfig.call(this, { stv_host: next });
    return next;
}

function stvCurrentHostLabel() {
    let cur = getStvHost.call(this);
    let list = getStvHosts();
    let idx = list.indexOf(cur);
    return (idx >= 0 ? (idx + 1) + '/' + list.length + ' · ' : '') + cur;
}

function getHost() {
    let { source } = this;
    let c = getConfig.call(this);
    if (c.host) return String(c.host).replace(/\/+$/, '');
    let base = '';
    try { base = "https://tingx.abrdns.com"; } catch (e) {}
    if (!base && typeof baseUrl !== 'undefined' && baseUrl) base = String(baseUrl);
    if (!base) base = getHosts()[0];
    return base.replace(/\/+$/, '');
}

function getConfig() {
    let { source } = this;
    try {
        let configStr = source.getVariable();
        if (!configStr || configStr.trim() == "") return {};
        let config = JSON.parse(configStr);
        if (Array.isArray(config)) return config[0] || {};
        if (config && typeof config == 'object') return config;
        return {};
    } catch (e) { return {}; }
}

function setConfig(obj) {
    let { source } = this;
    try {
        let config = getConfig.call(this);
        for (let k in obj) { if (obj.hasOwnProperty(k)) config[k] = obj[k]; }
        source.setVariable(JSON.stringify([config]));
        return true;
    } catch (e) { return false; }
}

function ensureConfig() {
    let c = getConfig.call(this);
    let changed = false;
    if (!c.gender) { c.gender = 'boy'; changed = true; }
    if (c.source == undefined) { c.source = ''; changed = true; }
    if (!c.sources) { c.sources = { novel: [], audio: [], comic: [], video: [], download: [] }; changed = true; }
    if (changed) setConfig.call(this, c);
    return c;
}

function deviceType() {
    let { java } = this;
    try {
        var id = java.deviceID();
        if (id && id !== '') {
            return true;
        }
    } catch (e) {}

    try {
        var id = java.androidId();
        if (id && id !== '') {
            return false;
        }
    } catch (e) {}

    return false;
}

function getDeviceId() {
    let { java } = this;
    let dev = '';
    try { let id1 = java.deviceID(); if (id1 && String(id1) !== '') dev = String(id1); } catch (e) {}
    if (!dev) { try { let id2 = java.androidId(); if (id2 && String(id2) !== '') dev = String(id2); } catch (e) {} }
    return dev;
}

function checkMsg(res) {
    let { java } = this;
    try {
        let obj = JSON.parse(res);
        if (obj.code !== 0) {
            java.toast(obj.message);
        }
    } catch (e) {}
    return res;
}

function getToken() {
    let { source } = this;
    let b64 = '';
    try { b64 = String(source.getLoginHeader() || '').trim(); } catch (e) {}
    return { b64: b64 };
}

function buildHeaders() {
    let { java } = this;
    let t = getToken.call(this);
    let dev = getDeviceId.call(this);
    let ts = String(Math.floor(Date.now() / 1000));

    let plain = '';
    if (t.b64) {
        try { plain = java.base64Decode(t.b64); } catch (e) { plain = ''; }
    }

    return {
        'User-Agent': java.getWebViewUA(),
        'x-novel-token': t.b64,
        'x-novel-deviceid': dev,
        'x-novel-timestamap': ts,
        'x-novel-public': java.md5Encode(plain + dev + ts).toLowerCase(),
        'x-novel-version': '10'
    };
}

function postJson(path, obj) {
    let { java } = this;
    let headers = buildHeaders.call(this);
    headers['Content-Type'] = 'application/json';
    let opt = { method: 'POST', body: JSON.stringify(obj || {}), headers: headers };
    let res = java.ajax(getHost.call(this) + path + ',' + JSON.stringify(opt));
    res = decryptIfEncrypted.call(this, res);
    try { return JSON.parse(res); } catch (e) { return { code: -1, message: '解析失败', raw: res }; }
}

function getSourceList() {
    let list = [];
    try {
        let arr = postJson.call(this, '/api/source', {});
        if (Array.isArray(arr)) {
            arr.forEach(function (it) { if (it && it.enabled && it.name) list.push(it); });
            list.sort(function (a, b) { return (a.sort || 0) - (b.sort || 0); });
        }
    } catch (e) {}
    return list;
}

function getCmtBrowserOptions() {
    return {
        expandedCornersRadius: 20,
        dismissOnTouchOutside: true,
        isDraggable: true,
        shouldDimBackground: true,
        backgroundDimAmount: 0.5,
        hardwareAccelerated: true,
        isNestedScrollingEnabled: true,
        isGestureInsetBottomIgnored: true,
        setFitToContents: false,
        heightPercentage: 0.75,
        isHideable: true
    };
}

function showCmt(bid, cid, para, date, sourceName) {
    let { java } = this;
    let session = getSessionId.call(this) || getSessionIdFromCookie.call(this) || '';
    let url = getHost.call(this) + '/comment'
            + '?tab=paras&book_id=' + bid
            + '&item_id=' + cid
            + '&para=' + para
            + '&source=' + (sourceName || '')
            + '&session=' + session;
    try {
        java.showBrowser(url, null, 'window.java=java;', JSON.stringify(getCmtBrowserOptions.call(this)));
    } catch (e) {
        try { java.startBrowser(url, '段评'); } catch (e2) {
            java.toast('打开段评失败：' + e2);
        }
    }
}

function getSessionId() {
    let config = getConfig.call(this);
    return String(config.fanqie_sessionid || '');
}

function getSessionIdFromCookie() {
    const { cookie } = this;
    try {
        let cookieHeader = String(cookie.getCookie('fanqienovel.com'));
        let sessionId = cookieHeader.match(/sessionid=([^;]+)/)?.[1] || null;
        if (sessionId) return sessionId;
    } catch (e) {}
    return "";
}

function getJjToken() {
    let { source } = this;
    let config = getConfig.call(this);

    let loginInfoKey = '';
    try {
        let info = source.getLoginInfoMap() || {};
        loginInfoKey = String(info.get('晋江登录Token') || '').trim();
    } catch (e) {}

    if (loginInfoKey) return loginInfoKey;

    return String(config.jj_token || '').trim();
}

function buildJjHeaders() {
    let { java } = this;
    return {
        "source": "android",
        "versiontype": "reading",
        "versioncode": "467",
        "version-code": "467",
        "User-Agent": java.getWebViewUA()
    };
}

function jjEncode(data) {
    let { java } = this;
    return java.createSymmetricCrypto("DES/CBC/PKCS5Padding", "KW8Dvm2N", "1ae2c94b").encryptBase64(data);
}

function isShelfSyncEnabled() {
    try {
        return String(getConfig.call(this).shelf_sync || 'off') == 'on';
    } catch (e) {
        return false;
    }
}

function syncShelf(isAdd) {
    let { java, book } = this;
    try {
        if (!book || !book.tocUrl) return;
        let raw = String(book.tocUrl || '').replace(/\\/g, '').replace(/^data:catalogUrl;base64,/, '');
        let idx = raw.indexOf(',');
        if (idx >= 0) raw = raw.substring(0, idx);
        raw = raw.replace(/[^A-Za-z0-9+/=]/g, '');
        let catalog = JSON.parse(String(java.base64Decode(raw) || '').replace(/\\/g, ''));
        let sourceName = String(catalog.source || '');
        let bookId = String(catalog.book_id || catalog.bookid || '');
        if (!bookId) return;

        let apiSource = '';
        let logins = '';
        if (sourceName.indexOf('番茄') >= 0) {
            apiSource = '番茄';
            logins = getSessionId.call(this) || getSessionIdFromCookie.call(this);
        } else if (sourceName.indexOf('晋江') >= 0) {
            apiSource = '晋江';
            logins = getJjToken.call(this);
        }
        if (!apiSource || !logins) {
            java.toast('书架同步：请先登录' + apiSource);
            return;
        }

        let res = postJson.call(this, '/api/bookshelf/sync', {
            source: apiSource,
            logins: String(logins),
            book_id: bookId,
            action: isAdd ? 'add' : 'del',
            group: ''
        });
        if (res && res.code == 0) {
            java.toast((isAdd ? '已同步到' : '已从') + apiSource + (isAdd ? '书架' : '书架移除'));
        } else {
            java.toast((res && res.message) || '书架同步失败');
        }
    } catch (e) {
        java.log('syncShelf error: ' + e);
        java.toast('书架同步失败');
    }
}

function syncProgress(chapterParams) {
    let { java } = this;
    try {
        let conf = getConfig.call(this);
        if ((conf.progress_sync || 'off') != 'on') return;

        let sourceName = String(chapterParams.source || '');
        let logins = '';
        if (/^晋江/.test(sourceName)) {
            logins = String(conf.jj_token || '');
        } else if (/^番茄/.test(sourceName)) {
            logins = String(conf.fanqie_sessionid || '');
        }
        if (!logins) return;

        let headers = buildHeaders.call(this);
        headers['Content-Type'] = 'application/json';

        let body = JSON.stringify({
            source: sourceName,
            book_id: String(chapterParams.book_id || ''),
            item_id: String(chapterParams.item_id || ''),
            logins: logins
        });

        let opt = { method: 'POST', body: body, headers: headers };
        let res = java.ajax(getHost.call(this) + '/api/progress,' + JSON.stringify(opt));
        res = decryptIfEncrypted.call(this, res);
        let obj = JSON.parse(res);
        if (obj.code !== 0) java.log('进度同步失败：' + (obj.message || '未知错误'));
    } catch (e) {
        java.log('进度同步异常：' + e);
    }
}

function decryptIfEncrypted(res) {
    let raw = String(res == undefined || res == null ? '' : res).trim();
    if (!raw) return res;

    if (raw.indexOf('"aes-256-gcm"') >= 0 && raw.charAt(0) == '{') {
        try {
            let obj = JSON.parse(raw);
            if (obj.alg == 'aes-256-gcm' && obj.data && obj.iv && obj.tag) {
                return aesGcmDecrypt.call(this, raw);
            }
            if (obj.data && typeof obj.data == 'object' && obj.data.alg == 'aes-256-gcm') {
                let dec = aesGcmDecrypt.call(this, obj.data);
                try { obj.data = JSON.parse(dec); }
                catch (e) { obj.data = dec; }
                return JSON.stringify(obj);
            }
        } catch (e) {}
    }
    return res;
}

function aesGcmDecrypt(payload) {
    let { java } = this;
    let obj = null;
    try {
        obj = (typeof payload == 'string') ? JSON.parse(payload) : payload;
        if (!obj || obj.alg !== 'aes-256-gcm' || !obj.data || !obj.iv || !obj.tag) return payload;
    } catch (e) { return payload; }

    try {
        let C = Packages.javax.crypto.Cipher;
        let K = Packages.javax.crypto.spec.SecretKeySpec;
        let G = Packages.javax.crypto.spec.GCMParameterSpec;
        let S = Packages.java.lang.String;
        let A = Packages.java.util.Arrays;
        let Sys = Packages.java.lang.System;

        let keyBytes = new S("Lk4#Fj9&Gh1*Ds6^Qw3!Er8@Ty5%Ui0o").getBytes("UTF-8");
        let ivBytes = java.base64DecodeToByteArray(obj.iv);
        let tagBytes = java.base64DecodeToByteArray(obj.tag);
        let dataBytes = java.base64DecodeToByteArray(obj.data);

        let combined = A.copyOf(dataBytes, dataBytes.length + tagBytes.length);
        Sys.arraycopy(tagBytes, 0, combined, dataBytes.length, tagBytes.length);

        let cipher = C.getInstance("AES/GCM/NoPadding");
        cipher.init(C.DECRYPT_MODE, new K(keyBytes, "AES"), new G(128, ivBytes));
        return new S(cipher.doFinal(combined), "UTF-8").toString();
    } catch (e) {}

    try {
        function b64dec(s) {
            let T = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
            let out = [], v = 0, bits = 0;
            s = String(s).replace(/[^A-Za-z0-9+/]/g, '');
            for (let i = 0; i < s.length; i++) {
                v = (v << 6) | T.indexOf(s.charAt(i));
                bits += 6;
                if (bits >= 8) { bits -= 8; out.push((v >> bits) & 0xFF); }
            }
            return out;
        }
        function utf8dec(plain) {
            let s = '', buf = [];
            for (let i = 0; i < plain.length; i++) {
                let c = plain[i];
                if (c < 0x80) buf.push(c);
                else if (c < 0xE0) buf.push(((c & 0x1F) << 6) | (plain[++i] & 0x3F));
                else if (c < 0xF0) buf.push(((c & 0x0F) << 12) | ((plain[++i] & 0x3F) << 6) | (plain[++i] & 0x3F));
                else {
                    let cp = ((c & 0x07) << 18) | ((plain[++i] & 0x3F) << 12) | ((plain[++i] & 0x3F) << 6) | (plain[++i] & 0x3F);
                    cp -= 0x10000;
                    buf.push(0xD800 + (cp >> 10), 0xDC00 + (cp & 0x3FF));
                }
                if (buf.length > 4096) { s += String.fromCharCode.apply(null, buf); buf = []; }
            }
            s += String.fromCharCode.apply(null, buf);
            return s;
        }

        let SBOX = [
            0x63,0x7c,0x77,0x7b,0xf2,0x6b,0x6f,0xc5,0x30,0x01,0x67,0x2b,0xfe,0xd7,0xab,0x76,
            0xca,0x82,0xc9,0x7d,0xfa,0x59,0x47,0xf0,0xad,0xd4,0xa2,0xaf,0x9c,0xa4,0x72,0xc0,
            0xb7,0xfd,0x93,0x26,0x36,0x3f,0xf7,0xcc,0x34,0xa5,0xe5,0xf1,0x71,0xd8,0x31,0x15,
            0x04,0xc7,0x23,0xc3,0x18,0x96,0x05,0x9a,0x07,0x12,0x80,0xe2,0xeb,0x27,0xb2,0x75,
            0x09,0x83,0x2c,0x1a,0x1b,0x6e,0x5a,0xa0,0x52,0x3b,0xd6,0xb3,0x29,0xe3,0x2f,0x84,
            0x53,0xd1,0x00,0xed,0x20,0xfc,0xb1,0x5b,0x6a,0xcb,0xbe,0x39,0x4a,0x4c,0x58,0xcf,
            0xd0,0xef,0xaa,0xfb,0x43,0x4d,0x33,0x85,0x45,0xf9,0x02,0x7f,0x50,0x3c,0x9f,0xa8,
            0x51,0xa3,0x40,0x8f,0x92,0x9d,0x38,0xf5,0xbc,0xb6,0xda,0x21,0x10,0xff,0xf3,0xd2,
            0xcd,0x0c,0x13,0xec,0x5f,0x97,0x44,0x17,0xc4,0xa7,0x7e,0x3d,0x64,0x5d,0x19,0x73,
            0x60,0x81,0x4f,0xdc,0x22,0x2a,0x90,0x88,0x46,0xee,0xb8,0x14,0xde,0x5e,0x0b,0xdb,
            0xe0,0x32,0x3a,0x0a,0x49,0x06,0x24,0x5c,0xc2,0xd3,0xac,0x62,0x91,0x95,0xe4,0x79,
            0xe7,0xc8,0x37,0x6d,0x8d,0xd5,0x4e,0xa9,0x6c,0x56,0xf4,0xea,0x65,0x7a,0xae,0x08,
            0xba,0x78,0x25,0x2e,0x1c,0xa6,0xb4,0xc6,0xe8,0xdd,0x74,0x1f,0x4b,0xbd,0x8b,0x8a,
            0x70,0x3e,0xb5,0x66,0x48,0x03,0xf6,0x0e,0x61,0x35,0x57,0xb9,0x86,0xc1,0x1d,0x9e,
            0xe1,0xf8,0x98,0x11,0x69,0xd9,0x8e,0x94,0x9b,0x1e,0x87,0xe9,0xce,0x55,0x28,0xdf,
            0x8c,0xa1,0x89,0x0d,0xbf,0xe6,0x42,0x68,0x41,0x99,0x2d,0x0f,0xb0,0x54,0xbb,0x16
        ];
        function xtime(a) { return ((a << 1) ^ (a & 0x80 ? 0x1b : 0)) & 0xFF; }
        function gmul(a, b) {
            let p = 0;
            for (let i = 0; i < 8; i++) {
                if (b & 1) p ^= a;
                let hi = a & 0x80;
                a = (a << 1) & 0xFF;
                if (hi) a ^= 0x1b;
                b >>= 1;
            }
            return p;
        }
        function expandKey(key) {
            let Nk = 8, w = [], rcon = 1;
            for (let i = 0; i < Nk; i++) w.push([key[4*i], key[4*i+1], key[4*i+2], key[4*i+3]]);
            for (let i = Nk; i < 60; i++) {
                let t = w[i-1].slice();
                if (i % Nk == 0) {
                    t = [t[1], t[2], t[3], t[0]].map(x => SBOX[x]);
                    t[0] ^= rcon;
                    rcon = xtime(rcon);
                } else if (i % Nk == 4) {
                    t = t.map(x => SBOX[x]);
                }
                w.push([w[i-Nk][0]^t[0], w[i-Nk][1]^t[1], w[i-Nk][2]^t[2], w[i-Nk][3]^t[3]]);
            }
            let rk = [];
            for (let i = 0; i < w.length; i++) rk.push(w[i][0], w[i][1], w[i][2], w[i][3]);
            return rk;
        }
        function encryptBlock(rk, input) {
            let st = input.slice(0, 16);
            for (let i = 0; i < 16; i++) st[i] ^= rk[i];
            for (let round = 1; round <= 14; round++) {
                for (let i = 0; i < 16; i++) st[i] = SBOX[st[i]];
                let t = st.slice();
                for (let r = 1; r < 4; r++)
                    for (let c = 0; c < 4; c++)
                        st[r + 4*c] = t[r + 4*((c + r) % 4)];
                if (round !== 14) {
                    for (let c = 0; c < 4; c++) {
                        let i = 4*c;
                        let a0 = st[i], a1 = st[i+1], a2 = st[i+2], a3 = st[i+3];
                        st[i]   = gmul(a0,2)^gmul(a1,3)^a2^a3;
                        st[i+1] = a0^gmul(a1,2)^gmul(a2,3)^a3;
                        st[i+2] = a0^a1^gmul(a2,2)^gmul(a3,3);
                        st[i+3] = gmul(a0,3)^a1^a2^gmul(a3,2);
                    }
                }
                for (let i = 0; i < 16; i++) st[i] ^= rk[round*16 + i];
            }
            return st;
        }
        function gfMul(x, y) {
            let z = new Array(16).fill(0);
            let v = y.slice();
            for (let i = 0; i < 128; i++) {
                if ((x[i >> 3] >> (7 - (i & 7))) & 1) {
                    for (let j = 0; j < 16; j++) z[j] ^= v[j];
                }
                let lsb = v[15] & 1;
                for (let j = 15; j > 0; j--) v[j] = ((v[j] >> 1) | ((v[j-1] & 1) << 7)) & 0xFF;
                v[0] >>= 1;
                if (lsb) v[0] ^= 0xE1;
            }
            return z;
        }
        function writeBitsBE(arr, offset, bits) {
            for (let i = 0; i < 8; i++) {
                arr[offset + 7 - i] = bits % 256;
                bits = Math.floor(bits / 256);
            }
        }
        function ghash(H, data, aadBits, ctBits) {
            let y = new Array(16).fill(0);
            for (let i = 0; i < data.length; i += 16) {
                let block = new Array(16).fill(0);
                for (let j = 0; j < 16 && i + j < data.length; j++) block[j] = data[i+j];
                for (let j = 0; j < 16; j++) y[j] ^= block[j];
                y = gfMul(y, H);
            }
            let lenBlock = new Array(16).fill(0);
            writeBitsBE(lenBlock, 0, aadBits);
            writeBitsBE(lenBlock, 8, ctBits);
            for (let j = 0; j < 16; j++) y[j] ^= lenBlock[j];
            y = gfMul(y, H);
            return y;
        }
        function inc32(block) {
            for (let i = 15; i >= 12; i--) {
                block[i] = (block[i] + 1) & 0xFF;
                if (block[i] !== 0) break;
            }
        }
        function gcmDecrypt(key, iv, ct, tag) {
            let rk = expandKey(key);
            let H = encryptBlock(rk, new Array(16).fill(0));
            let J0;
            if (iv.length == 12) J0 = iv.concat([0, 0, 0, 1]);
            else J0 = ghash(H, iv, 0, iv.length * 8);
            let S = ghash(H, ct, 0, ct.length * 8);
            let ej0 = encryptBlock(rk, J0);
            let calcTag = new Array(16);
            for (let i = 0; i < 16; i++) calcTag[i] = S[i] ^ ej0[i];
            for (let i = 0; i < 16; i++) {
                if (calcTag[i] !== tag[i]) return null;
            }
            let out = [];
            let ctr = J0.slice();
            for (let i = 0; i < ct.length; i += 16) {
                inc32(ctr);
                let ks = encryptBlock(rk, ctr);
                for (let j = 0; j < 16 && i + j < ct.length; j++) {
                    out.push(ct[i+j] ^ ks[j]);
                }
            }
            return out;
        }

        let key = [];
        let keyStr = "Lk4#Fj9&Gh1*Ds6^Qw3!Er8@Ty5%Ui0o";
        for (let i = 0; i < keyStr.length; i++) key.push(keyStr.charCodeAt(i) & 0xFF);

        let iv = b64dec(obj.iv);
        let tag = b64dec(obj.tag);
        let ct = b64dec(obj.data);

        let plain = gcmDecrypt(key, iv, ct, tag);
        if (!plain) return payload;
        return utf8dec(plain);
    } catch (e) {
        return payload;
    }
}

