function selectSource() {
    let { java } = this;
    var base = getHost.call(this);
    var list = [];
    try {
        var opt = { method: 'POST', body: '{}' };
        var res = java.ajax(base + '/api/source,' + JSON.stringify(opt));
        var arr = JSON.parse(res);
        if (Array.isArray(arr)) {
            for (var i = 0; i < arr.length; i++) {
                var it = arr[i];
                if (it && it.enabled && it.name) list.push(it);
            }
            list.sort(function (a, b) { return (a.sort || 0) - (b.sort || 0); });
        }
    } catch (e) {
        java.toast('源站列表请求失败：' + e);
        return;
    }
    if (!list.length) { java.toast('源站列表为空'); return; }

    var conf = getConfig.call(this);
    var TABS = ['novel', 'audio', 'comic', 'video', 'download'];
    var TAB_LABEL = { novel: '小说', audio: '听书', comic: '漫画', video: '短剧', download: '下载' };
    var TAB_ICON = { novel: 'fa-book-open', audio: 'fa-headphones', comic: 'fa-images', video: 'fa-film', download: 'fa-download' };

    var sourcesCfg = conf.sources || {};
    TABS.forEach(function (t) { if (!Array.isArray(sourcesCfg[t])) sourcesCfg[t] = []; });

    var allCfg = Array.isArray(conf.allTabs) ? conf.allTabs.slice() : [];
    TABS.forEach(function (t) {
        if (sourcesCfg[t].length > 0 && allCfg.indexOf(t) !== -1) {
            allCfg = allCfg.filter(function (x) { return x !== t; });
        }
    });

    var tabMap = {};
    for (var i = 0; i < list.length; i++) {
        var item = list[i];
        var tab = item.tab || 'novel';
        if (TABS.indexOf(tab) == -1) continue;
        if (!tabMap[tab]) tabMap[tab] = [];
        tabMap[tab].push(item);
    }

    var tabsData = [];
