    var host = getHost.call(this);
    var versionApi = host + '/api/version?aid=sy';
    var siteApi = host + '/api/site/public';

    function esc(v) {
        return String(v == undefined ? '' : v)
            .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
    }

    var siteName = '书源更新';
    try {
        var siteRes = java.ajax(siteApi);
        var siteObj = JSON.parse(siteRes);
        if (siteObj && siteObj.data && siteObj.data.site_name) {
            siteName = String(siteObj.data.site_name);
        }
    } catch (e) {}

    var res;
