var ao3Origin = "https://archiveofourown.org";
var ao3LoginUrl = ao3Origin + "/users/login";
var ao3AccountField = "AO3 用户名或邮箱";
var ao3PasswordField = "AO3 密码";
var ao3VerificationHint = "请点「人工验证后登录」，完成官网验证后点浏览器右上角的 ✓。";

function readAO3Credentials(values) {
  var account = values ? String(values.get(ao3AccountField) || "").trim() : "";
  var password = values ? String(values.get(ao3PasswordField) || "") : "";
  if (!account || !password) throw new Error("请填写 AO3 用户名或邮箱和密码。");
  return {account: account, password: password};
}

function readAO3Cookies() {
  var cookies = Object.create(null);
  String(cookie.getCookie(ao3Origin) || "").split(";").forEach(function (part) {
    var separator = part.indexOf("=");
    if (separator < 1) return;
    var name = part.slice(0, separator).trim();
    if (name) cookies[name] = part.slice(separator + 1).trim();
  });
  return cookies;
}

function ao3CookieHeader(cookies) {
  return Object.keys(cookies).map(function (name) {
    return name + "=" + cookies[name];
  }).join("; ");
}

function ao3Request(url, cookies, form) {
  var response;
  try {
    var request = org.jsoup.Jsoup.connect(url)
      .followRedirects(false)
      .ignoreHttpErrors(true)
      .userAgent(java.getWebViewUA())
      .timeout(20000);
    var cookieHeader = ao3CookieHeader(cookies);
    if (cookieHeader) request.header("Cookie", cookieHeader);
    if (form) {
      request.method(org.jsoup.Connection.Method.POST)
        .header("Origin", ao3Origin)
        .referrer(ao3LoginUrl)
        .data("authenticity_token", form.token)
        .data("user[login]", form.account)
        .data("user[password]", form.password)
        .data("user[remember_me]", "1");
    }
    response = request.execute();
    var incoming = response.cookies().entrySet().iterator();
    while (incoming.hasNext()) {
      var entry = incoming.next();
      var key = String(entry.getKey());
      var value = String(entry.getValue());
      if (value) cookies[key] = value;
      else delete cookies[key];
    }
  } catch (error) {
    throw new Error("连接 AO3 失败。可以点「打开官网登录」继续。");
  }
  return response;
}

function checkAO3Verification(status) {
  if (status === 403 || status === 503) throw new Error(ao3VerificationHint);
  if (status === 429) throw new Error("AO3 暂时限制了请求，请稍后再试。");
}

function hasAO3Login(page) {
  return !!page.selectFirst("#greeting ul.user a[href^='/users/logout']");
}

function loginWithAO3(credentials) {
  var cookies = readAO3Cookies();
  var entry = ao3Request(ao3LoginUrl, cookies);
  var status = entry.statusCode();
  checkAO3Verification(status);
  if (status === 302 || status === 303) {
    var active = ao3Request(ao3Origin + "/", cookies);
    checkAO3Verification(active.statusCode());
    if (active.statusCode() === 200 && hasAO3Login(active.parse())) {
      cookie.setCookie(ao3Origin, ao3CookieHeader(cookies));
      return;
    }
  }
  if (status !== 200) throw new Error("AO3 登录页暂不可用。可以点「打开官网登录」继续。");

  var page = entry.parse();
  var form = page.selectFirst("#loginform form[method=post]");
  var tokenInput = form && form.selectFirst("input[name=authenticity_token]");
  if (!tokenInput || String(form.absUrl("action")).split("?")[0] !== ao3LoginUrl) {
    throw new Error(ao3VerificationHint);
  }
  var token = String(tokenInput.attr("value"));
  if (!token) throw new Error(ao3VerificationHint);

  var reply = ao3Request(ao3LoginUrl, cookies, {
    token: token,
    account: credentials.account,
    password: credentials.password
  });
  var replyStatus = reply.statusCode();
  checkAO3Verification(replyStatus);
  if (replyStatus === 422) throw new Error(ao3VerificationHint);
  if (replyStatus === 302 || replyStatus === 303) {
    var home = ao3Request(ao3Origin + "/", cookies);
    checkAO3Verification(home.statusCode());
    if (home.statusCode() === 200 && hasAO3Login(home.parse())) {
      cookie.setCookie(ao3Origin, ao3CookieHeader(cookies));
      return;
    }
  }
  throw new Error("AO3 未确认登录。请核对账号密码，或点「打开官网登录」查看网站提示。");
}

function login() {
  loginWithAO3(readAO3Credentials(source.getLoginInfoMap()));
}

function waitForAO3Browser(title) {
  try {
    java.startBrowserAwait(ao3LoginUrl, title, false);
  } catch (error) {
    return false;
  }
  return true;
}

function verifyThenLoginAO3(values) {
  try {
    var credentials = readAO3Credentials(values);
    if (!waitForAO3Browser("AO3 人工验证 · 完成后点 ✓")) return;
    loginWithAO3(credentials);
    var saved = {};
    saved[ao3AccountField] = credentials.account;
    saved[ao3PasswordField] = credentials.password;
    if (!source.putLoginInfo(JSON.stringify(saved))) {
      java.toast("已登录 AO3。Legado 未能保存这次输入的账号密码。");
      return;
    }
    java.toast("已登录 AO3，账号密码已保存。");
  } catch (error) {
    java.toast(error.message || "登录暂时无法完成，请在官网重试。");
  }
}

function openAO3Login() {
  waitForAO3Browser("AO3 官网登录 · 完成后点 ✓");
}

