@js:(function () {
  var origin = "https://archiveofourown.org";
  var publicCategories = [{"title":"中文 · 最近更新","url":"https://archiveofourown.org/works/search?work_search%5Blanguage_id%5D=zh&work_search%5Bsort_column%5D=revised_at&work_search%5Bsort_direction%5D=desc&page={{page}}"},{"title":"中文 · 已完结","url":"https://archiveofourown.org/works/search?work_search%5Blanguage_id%5D=zh&work_search%5Bcomplete%5D=T&work_search%5Bsort_column%5D=revised_at&work_search%5Bsort_direction%5D=desc&page={{page}}"},{"title":"中文 · 最多 Kudos","url":"https://archiveofourown.org/works/search?work_search%5Blanguage_id%5D=zh&work_search%5Bsort_column%5D=kudos_count&work_search%5Bsort_direction%5D=desc&page={{page}}"},{"title":"英文 · 最近更新","url":"https://archiveofourown.org/works/search?work_search%5Blanguage_id%5D=en&work_search%5Bsort_column%5D=revised_at&work_search%5Bsort_direction%5D=desc&page={{page}}"},{"title":"全站 · 最近更新","url":"https://archiveofourown.org/works/search?work_search%5Bsort_column%5D=revised_at&work_search%5Bsort_direction%5D=desc&page={{page}}"},{"title":"全站 · 已完结","url":"https://archiveofourown.org/works/search?work_search%5Bcomplete%5D=T&work_search%5Bsort_column%5D=revised_at&work_search%5Bsort_direction%5D=desc&page={{page}}"},{"title":"全站 · 连载中","url":"https://archiveofourown.org/works/search?work_search%5Bcomplete%5D=F&work_search%5Bsort_column%5D=revised_at&work_search%5Bsort_direction%5D=desc&page={{page}}"},{"title":"Gen","url":"https://archiveofourown.org/tags/Gen/works?page={{page}}"},{"title":"M/M","url":"https://archiveofourown.org/tags/M*s*M/works?page={{page}}"},{"title":"F/F","url":"https://archiveofourown.org/tags/F*s*F/works?page={{page}}"},{"title":"F/M","url":"https://archiveofourown.org/tags/F*s*M/works?page={{page}}"},{"title":"Multi","url":"https://archiveofourown.org/tags/Multi/works?page={{page}}"},{"title":"Other","url":"https://archiveofourown.org/tags/Other/works?page={{page}}"}];
  var categories = [];
  var seen = {};

  function addCategory(title, url) {
    if (!title || !url || seen[title + "\n" + url]) return;
    seen[title + "\n" + url] = true;
    url = url.replace(/,/g, "%2C");
    categories.push({
      title: title,
      url: url + (url.indexOf("?") === -1 ? "?" : "&") + "page={{page}}"
    });
  }

  ao3SavedTags(source).forEach(function (tag) {
    addCategory("我的标签 · " + tag.title, tag.url);
  });

  function getPage(url) {
    try {
      var response = java.connect(url);
      var finalUrl = String(response.url());
      if (response.code() !== 200 || finalUrl.indexOf(origin + "/") !== 0) return null;
      return org.jsoup.Jsoup.parse(String(response.body() || ""), finalUrl);
    } catch (error) {
      return null;
    }
  }

  function getPath(link) {
    if (!link) return "";
    var url = String(link.absUrl("href"));
    return url.indexOf(origin + "/") === 0 ? url.slice(origin.length) : "";
  }

  function collectCategories(startUrl, selector, pattern, prefix, suffix) {
    var firstPath = startUrl.slice(origin.length).split("?")[0];
    var visited = {};
    var url = startUrl;
    while (url && !visited[url]) {
      visited[url] = true;
      var page = getPage(url);
      if (!page) break;
      var links = page.select(selector);
      for (var i = 0; i < links.size(); i++) {
        var link = links.get(i);
        var linkPath = getPath(link);
        if (pattern.test(linkPath)) addCategory(prefix + link.text(), origin + linkPath + suffix);
      }

      var next = getPath(page.selectFirst("#main .pagination a[rel=next], #main .pagination a.next_page, #main .pagination li.next > a"));
      var pageNumber = next.split("?")[0] === firstPath && next.match(/[?&]page=([0-9]+)(?:&|$)/);
      url = pageNumber ? startUrl + "&page=" + pageNumber[1] : "";
    }
  }

  if (String(cookie.getCookie(origin) || "")) {
    var home = getPage(origin + "/");
    if (home) {
      var profile = getPath(home.selectFirst("#greeting ul.user > li.dropdown > a[href]"));
      var userPath = /^\/users\/[a-zA-Z0-9_-]+$/;
      if (userPath.test(profile)) {
        var bookmarks = origin + profile + "/bookmarks?bookmark_search%5Bbookmarkable_type%5D=";
        var subscriptions = origin + profile + "/subscriptions?type=";
        addCategory("收藏 · 作品", bookmarks + "Work");
        addCategory("订阅 · 作品", subscriptions + "works");

        var tags = home.select("#main .splash .favorite.module ul > li > a[href]");
        for (var i = 0; i < tags.size(); i++) {
          var tag = tags.get(i);
          var tagPath = getPath(tag);
          if (/^\/tags\/[^/?#]+\/works$/.test(tagPath)) {
            addCategory("收藏标签 · " + tag.text(), origin + tagPath);
          }
        }

        var seriesPath = /^\/series\/[0-9]+$/;
        if (home.selectFirst("#greeting a[href$='/subscriptions']")) {
          var subscriptionLinks = "#main dl.subscription.index > dt > a:first-child";
          collectCategories(subscriptions + "series", subscriptionLinks, seriesPath, "订阅系列 · ", "");
          collectCategories(subscriptions + "users", subscriptionLinks, userPath, "订阅作者 · ", "/works");
        }
        if (home.selectFirst("#greeting a[href$='/bookmarks']")) {
          collectCategories(bookmarks + "Series", "#main ol.bookmark.index > li.bookmark > div.header h4.heading > a[href^='/series/']", seriesPath, "收藏系列 · ", "");
        }
      }
    }
  }

  return JSON.stringify(categories.concat(publicCategories));
})();

