(function () {
  var pageUrl = String(result.url());
  var workPath = /^https:\/\/archiveofourown\.org(\/works\/[0-9]+(?:\/chapters\/[0-9]+)?)\/?(?:[?#]|$)/;
  var adultFlag = /[?&]view_adult=true(?:&|#|$)/;
  var work = pageUrl.match(workPath);
  if (!work || adultFlag.test(pageUrl) || result.code() !== 200) return result;

  var html = String(result.body() || "");
  if (html.indexOf("view_adult=true") === -1) return result;

  var page = org.jsoup.Jsoup.parse(html, pageUrl);
  if (!page.selectFirst("#main > p.caution.notice")) return result;

  var link = page.selectFirst("#main > ul.actions > li > a[href*='view_adult=true']");
  if (!link) return result;

  var nextUrl = String(link.absUrl("href"));
  var nextWork = nextUrl.match(workPath);
  if (!nextWork || nextWork[1] !== work[1] || !adultFlag.test(nextUrl)) return result;

  return java.connect(nextUrl);
})();

