var ao3SavedTagKey = "ao3.savedTags";
var ao3WorkTagKey = "ao3.workTags";

function ao3ParseTagData(value) {
  try {
    return JSON.parse(String(value || "null"));
  } catch (error) {
    return null;
  }
}

function ao3ReadTagData(source, key) {
  return ao3ParseTagData(source.get(key));
}

function ao3TagUrl(url) {
  var path = String(url || "").match(/^https://archiveofourown\.org/tags/([^/?#\s]+)/works/?(?:[?#].*)?$/);
  if (!path) return "";
  var tag = path[1].replace(/[,<>"'{}]/g, function (character) {
    return "%" + character.charCodeAt(0).toString(16).toUpperCase();
  }).replace(/%[0-9A-Fa-f]{2}/g, function (escape) {
    return escape.toUpperCase();
  });
  return "https://archiveofourown.org/tags/" + tag + "/works";
}

function ao3ValidTags(values) {
  if (!Array.isArray(values)) return [];
  var seen = Object.create(null);
  return values.reduce(function (tags, tag) {
    var url = tag && ao3TagUrl(tag.url);
    var title = tag && String(tag.title || "").trim();
    if (url && title && !seen[url]) {
      seen[url] = true;
      tags.push({title: title, url: url});
    }
    return tags;
  }, []);
}

function ao3SavedTags(source) {
  return ao3ValidTags(ao3ReadTagData(source, ao3SavedTagKey));
}

function ao3UpdateSavedTags(source, changes) {
  var saved = ao3SavedTags(source);
  var edits = Object.create(null);
  var existing = Object.create(null);
  var additions = ao3ValidTags(changes.additions);
  if (Array.isArray(changes.edits)) {
    changes.edits.forEach(function (entry) {
      var url = entry && ao3TagUrl(entry.url);
      if (!url) return;
      if (entry.title === null) edits[url] = null;
      else if (typeof entry.title === "string" && entry.title.trim()) edits[url] = entry.title.trim();
    });
  }
  var retained = [];
  saved.forEach(function (entry) {
    existing[entry.url] = true;
    var title = edits[entry.url];
    if (title !== null) retained.push({title: title || entry.title, url: entry.url});
  });
  var result = additions.filter(function (entry) {
    return !existing[entry.url];
  }).concat(retained);
  if (JSON.stringify(result) === JSON.stringify(saved)) return false;
  source.put(ao3SavedTagKey, JSON.stringify(result));
  return true;
}

function ao3RefreshTagCategories(source) {
  try {
    if (typeof source.refreshExplore === "function") {
      source.refreshExplore();
      return true;
    }
  } catch (error) {
    return false;
  }
  return false;
}

function ao3CodeValue(value) {
  return JSON.stringify(value).replace(/</g, "\u003c")
    .replace(/ /g, "\u2028").replace(/ /g, "\u2029");
}

