function parseVer(v) {
    return String(v || '').split('.').map(function (x) { return parseInt(x, 10) || 0; });
}

function cmpVer(a, b) {
    let pa = parseVer(a), pb = parseVer(b);
    let len = Math.max(pa.length, pb.length);
    for (let i = 0; i < len; i++) {
        let x = pa[i] || 0, y = pb[i] || 0;
        if (x > y) return 1;
        if (x < y) return -1;
    }
    return 0;
}

function shouldBlockByVersion(serverVerObj) {
    if (!serverVerObj || !serverVerObj.version) return false;
    let sv = String(serverVerObj.version);
    let lv = String(localVersion || '');
    if (cmpVer(sv, lv) <= 0) return false;

    let isForce = (serverVerObj.force == true || String(serverVerObj.force) == 'true');
    let tipMsg = serverVerObj.msg || '';   // ← 用 version.msg

    if (isForce) {
        try { java.toast('\n服务端要求强制更新 ' + sv + (tipMsg ? '\n' + tipMsg : '')); } catch (e) {}
        try { checkVersion.call(this); } catch (e) {}
    } else {
        try { java.toast('有新版本 ' + sv + (tipMsg ? '\n' + tipMsg : '') + '\n可在登录页「🔄更新检测」查看'); } catch (e) {}
    }

    return false;
}

function checkVersion() {
    let { java } = this;
    var host = getHost.call(this);
    var versionApi = host + '/api/version?aid=sy';
    var siteApi = host + '/api/site/public';

    function esc(v) {
        return String(v == undefined ? '' : v)
            .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
    }

    var siteName = '书源更新';
    try {
        var siteRes = java.ajax(siteApi);
        var siteObj = JSON.parse(siteRes);
        if (siteObj && siteObj.data && siteObj.data.site_name) {
            siteName = String(siteObj.data.site_name);
        }
    } catch (e) {}

    var res;
    try { res = java.ajax(versionApi); }
    catch (e) { java.toast('版本检查失败：网络异常'); return; }
    var obj;
    try { obj = JSON.parse(res); }
    catch (e) { java.toast('版本检查失败：返回解析异常'); return; }
    if (!obj || obj.code !== 0 || !obj.data || !obj.data.version) {
        java.toast((obj && obj.message) || '版本检查失败'); return;
    }

    var serverVer = String(obj.data.version);
    var myLocalVer = String(localVersion || '');
    var cmp = cmpVer(serverVer, myLocalVer);   // 复用 jsLib 的 cmpVer

    if (cmp > 0) {
        var msg = String(obj.data.msg || '有新版本啦');
        var force = String(obj.data.force || 'false') == 'true';
        var downloadUrl = String(obj.data.download_url || '');
        var updateLog = obj.data.update_log || {};

        var dates = Object.keys(updateLog).filter(function (d) {
            return Array.isArray(updateLog[d]) && updateLog[d].length;
        }).sort(function (a, b) { return b.localeCompare(a); });

        var latestDate = dates[0] || '';
        var latestItems = latestDate ? updateLog[latestDate] : [];
        var historyDates = dates.slice(1);

        var latestLogHtml = '';
        latestItems.forEach(function (t) {
            latestLogHtml += '<div class="update-text">' + esc(t) + '</div>';
        });

        var historyHtml = '';
        historyDates.forEach(function (d) {
