                a = (a << 1) & 0xFF;
                if (hi) a ^= 0x1b;
                b >>= 1;
            }
            return p;
        }
        function expandKey(key) {
            let Nk = 8, w = [], rcon = 1;
            for (let i = 0; i < Nk; i++) w.push([key[4*i], key[4*i+1], key[4*i+2], key[4*i+3]]);
            for (let i = Nk; i < 60; i++) {
                let t = w[i-1].slice();
                if (i % Nk == 0) {
                    t = [t[1], t[2], t[3], t[0]].map(x => SBOX[x]);
                    t[0] ^= rcon;
                    rcon = xtime(rcon);
                } else if (i % Nk == 4) {
                    t = t.map(x => SBOX[x]);
                }
                w.push([w[i-Nk][0]^t[0], w[i-Nk][1]^t[1], w[i-Nk][2]^t[2], w[i-Nk][3]^t[3]]);
            }
            let rk = [];
            for (let i = 0; i < w.length; i++) rk.push(w[i][0], w[i][1], w[i][2], w[i][3]);
            return rk;
        }
        function encryptBlock(rk, input) {
            let st = input.slice(0, 16);
            for (let i = 0; i < 16; i++) st[i] ^= rk[i];
            for (let round = 1; round <= 14; round++) {
                for (let i = 0; i < 16; i++) st[i] = SBOX[st[i]];
                let t = st.slice();
                for (let r = 1; r < 4; r++)
                    for (let c = 0; c < 4; c++)
                        st[r + 4*c] = t[r + 4*((c + r) % 4)];
                if (round !== 14) {
                    for (let c = 0; c < 4; c++) {
                        let i = 4*c;
                        let a0 = st[i], a1 = st[i+1], a2 = st[i+2], a3 = st[i+3];
                        st[i]   = gmul(a0,2)^gmul(a1,3)^a2^a3;
                        st[i+1] = a0^gmul(a1,2)^gmul(a2,3)^a3;
                        st[i+2] = a0^a1^gmul(a2,2)^gmul(a3,3);
                        st[i+3] = gmul(a0,3)^a1^a2^gmul(a3,2);
                    }
                }
                for (let i = 0; i < 16; i++) st[i] ^= rk[round*16 + i];
            }
            return st;
        }
        function gfMul(x, y) {
            let z = new Array(16).fill(0);
            let v = y.slice();
            for (let i = 0; i < 128; i++) {
                if ((x[i >> 3] >> (7 - (i & 7))) & 1) {
                    for (let j = 0; j < 16; j++) z[j] ^= v[j];
                }
                let lsb = v[15] & 1;
                for (let j = 15; j > 0; j--) v[j] = ((v[j] >> 1) | ((v[j-1] & 1) << 7)) & 0xFF;
                v[0] >>= 1;
                if (lsb) v[0] ^= 0xE1;
            }
            return z;
        }
        function writeBitsBE(arr, offset, bits) {
            for (let i = 0; i < 8; i++) {
                arr[offset + 7 - i] = bits % 256;
                bits = Math.floor(bits / 256);
            }
        }
        function ghash(H, data, aadBits, ctBits) {
            let y = new Array(16).fill(0);
            for (let i = 0; i < data.length; i += 16) {
                let block = new Array(16).fill(0);
                for (let j = 0; j < 16 && i + j < data.length; j++) block[j] = data[i+j];
                for (let j = 0; j < 16; j++) y[j] ^= block[j];
                y = gfMul(y, H);
            }
            let lenBlock = new Array(16).fill(0);
            writeBitsBE(lenBlock, 0, aadBits);
            writeBitsBE(lenBlock, 8, ctBits);
            for (let j = 0; j < 16; j++) y[j] ^= lenBlock[j];
            y = gfMul(y, H);
            return y;
        }
        function inc32(block) {
            for (let i = 15; i >= 12; i--) {
                block[i] = (block[i] + 1) & 0xFF;
                if (block[i] !== 0) break;
            }
        }
        function gcmDecrypt(key, iv, ct, tag) {
            let rk = expandKey(key);
            let H = encryptBlock(rk, new Array(16).fill(0));
            let J0;
            if (iv.length == 12) J0 = iv.concat([0, 0, 0, 1]);
            else J0 = ghash(H, iv, 0, iv.length * 8);
            let S = ghash(H, ct, 0, ct.length * 8);
            let ej0 = encryptBlock(rk, J0);
            let calcTag = new Array(16);
            for (let i = 0; i < 16; i++) calcTag[i] = S[i] ^ ej0[i];
            for (let i = 0; i < 16; i++) {
                if (calcTag[i] !== tag[i]) return null;
            }
            let out = [];
            let ctr = J0.slice();
            for (let i = 0; i < ct.length; i += 16) {
                inc32(ctr);
                let ks = encryptBlock(rk, ctr);
                for (let j = 0; j < 16 && i + j < ct.length; j++) {
                    out.push(ct[i+j] ^ ks[j]);
                }
            }
            return out;
        }

        let key = [];
        let keyStr = "Lk4#Fj9&Gh1*Ds6^Qw3!Er8@Ty5%Ui0o";
        for (let i = 0; i < keyStr.length; i++) key.push(keyStr.charCodeAt(i) & 0xFF);

        let iv = b64dec(obj.iv);
        let tag = b64dec(obj.tag);
        let ct = b64dec(obj.data);

        let plain = gcmDecrypt(key, iv, ct, tag);
        if (!plain) return payload;
        return utf8dec(plain);
    } catch (e) {
        return payload;
    }
}

