            'background:linear-gradient(90deg,transparent,rgba(255,255,255,.35),transparent);transform:rotate(30deg);' +
            'animation:btnShine 3s ease-in-out infinite}' +
            '@keyframes btnShine{0%,60%{transform:translateX(-120%) rotate(30deg)}80%,100%{transform:translateX(120%) rotate(30deg)}}' +
            '.btn:hover{background:linear-gradient(135deg,var(--primary) 0%,var(--primary-dark) 60%,var(--primary-dark) 100%);transform:translateY(-1px)}' +
            '.btn:active{transform:translateY(1px) scale(.98)}' +
            '.btn i,.btn span{position:relative;z-index:1}' +
            '.foot{margin-top:14px;text-align:center;color:var(--muted);font-size:12px;line-height:1.6}' +
            '@media(max-width:400px){.versions{flex-direction:column}.vs{transform:rotate(90deg)}.card{padding:18px 16px}}' +
            '</style></head><body>' +
            '<div class="waves"><div class="wave w1"></div><div class="wave w2"></div><div class="wave w3"></div></div>' +
            '<div class="wrap"><section class="card">' +
            '<div class="head">' +
            '<span class="eyebrow">Version Update</span>' +
            '<h1>' + esc(siteName) + '</h1>' +
            '<p>' + esc(msg) + '</p>' +
            '</div>' +
            '<div class="versions">' +
            '<div class="v-card"><div class="k"><i class="fas fa-cube"></i> 当前版本</div><div class="n">v' + esc(myLocalVer) + '</div><div class="d">您的当前版本</div></div>' +
            '<div class="vs"><i class="fas fa-arrow-right"></i></div>' +
            '<div class="v-card latest"><div class="k"><i class="fas fa-star"></i> 最新版本</div><div class="n">v' + esc(serverVer) + '</div><div class="d">可用最新版本</div></div>' +
            '</div>' +
            (latestLogHtml ? '<div class="section"><div class="section-head"><h2><i class="fas fa-bolt"></i> 最新更新</h2><span class="tag">最新发布</span></div><div class="section-body"><div class="log-date"><i class="fas fa-calendar-alt"></i>' + esc(latestDate) + '</div>' + latestLogHtml + '</div></div>' : '') +
            (downloadUrl ? '<a href="' + esc(downloadUrl) + '" class="btn"><i class="fas fa-rocket"></i><span>立即更新</span></a>' : '') +
            (historyHtml ? '<div class="section" style="padding:0"><div class="history-head" onclick="toggleLogs()"><h2><i class="fas fa-history"></i> 历史更新 <span>' + historyCountText + '</span></h2><button class="toggle"><span id="toggleText">展开历史</span><i class="fas fa-chevron-down" id="toggleIcon"></i></button></div><div class="history-body" id="logList">' + historyHtml + '</div></div>' : '') +
            '<p class="foot">' + (force ? '本次为强制更新，请更新后再使用书源' : '更新后返回书源即可生效') + '</p>' +
            '</section></div>' +
