                        st[i+1] = a0^gmul(a1,2)^gmul(a2,3)^a3;
                        st[i+2] = a0^a1^gmul(a2,2)^gmul(a3,3);
                        st[i+3] = gmul(a0,3)^a1^a2^gmul(a3,2);
                    }
                }
                for (let i = 0; i < 16; i++) st[i] ^= rk[round*16 + i];
            }
            return st;
        }
        function gfMul(x, y) {
            let z = new Array(16).fill(0);
            let v = y.slice();
            for (let i = 0; i < 128; i++) {
                if ((x[i >> 3] >> (7 - (i & 7))) & 1) {
                    for (let j = 0; j < 16; j++) z[j] ^= v[j];
                }
                let lsb = v[15] & 1;
                for (let j = 15; j > 0; j--) v[j] = ((v[j] >> 1) | ((v[j-1] & 1) << 7)) & 0xFF;
                v[0] >>= 1;
                if (lsb) v[0] ^= 0xE1;
            }
            return z;
        }
        function writeBitsBE(arr, offset, bits) {
            for (let i = 0; i < 8; i++) {
                arr[offset + 7 - i] = bits % 256;
                bits = Math.floor(bits / 256);
            }
        }
        function ghash(H, data, aadBits, ctBits) {
            let y = new Array(16).fill(0);
            for (let i = 0; i < data.length; i += 16) {
                let block = new Array(16).fill(0);
                for (let j = 0; j < 16 && i + j < data.length; j++) block[j] = data[i+j];
                for (let j = 0; j < 16; j++) y[j] ^= block[j];
                y = gfMul(y, H);
            }
            let lenBlock = new Array(16).fill(0);
            writeBitsBE(lenBlock, 0, aadBits);
            writeBitsBE(lenBlock, 8, ctBits);
            for (let j = 0; j < 16; j++) y[j] ^= lenBlock[j];
            y = gfMul(y, H);
            return y;
        }
        function inc32(block) {
            for (let i = 15; i >= 12; i--) {
                block[i] = (block[i] + 1) & 0xFF;
                if (block[i] !== 0) break;
            }
        }
        function gcmDecrypt(key, iv, ct, tag) {
            let rk = expandKey(key);
            let H = encryptBlock(rk, new Array(16).fill(0));
            let J0;
            if (iv.length == 12) J0 = iv.concat([0, 0, 0, 1]);
            else J0 = ghash(H, iv, 0, iv.length * 8);
            let S = ghash(H, ct, 0, ct.length * 8);
            let ej0 = encryptBlock(rk, J0);
            let calcTag = new Array(16);
            for (let i = 0; i < 16; i++) calcTag[i] = S[i] ^ ej0[i];
            for (let i = 0; i < 16; i++) {
                if (calcTag[i] !== tag[i]) return null;
            }
            let out = [];
            let ctr = J0.slice();
            for (let i = 0; i < ct.length; i += 16) {
                inc32(ctr);
                let ks = encryptBlock(rk, ctr);
                for (let j = 0; j < 16 && i + j < ct.length; j++) {
                    out.push(ct[i+j] ^ ks[j]);
                }
            }
            return out;
        }

        let key = [];
        let keyStr = "Lk4#Fj9&Gh1*Ds6^Qw3!Er8@Ty5%Ui0o";
        for (let i = 0; i < keyStr.length; i++) key.push(keyStr.charCodeAt(i) & 0xFF);

        let iv = b64dec(obj.iv);
        let tag = b64dec(obj.tag);
        let ct = b64dec(obj.data);

        let plain = gcmDecrypt(key, iv, ct, tag);
        if (!plain) return payload;
        return utf8dec(plain);
    } catch (e) {
        return payload;
    }
}

function getJjShelfClass() {
    let { java } = this;
    try {
        var token = getJjToken.call(this);
        if (!token) {
            java.toast("请先配置晋江登录Token");
            return;
        }

        var url = "https://app.jjwxc.org/app.jjwxc/android/reading/FavoriteClass/favoriteClass";
        var body = encode.call(this, JSON.stringify({
            "versionCode": "444",
            "token": token
        }));

        var headers = {
            "versioncode": "444",
            "versiontype": "reading",
            "User-Agent": java.getWebViewUA()
        };

        var res = java.post(url, body, headers).body();
        var data = JSON.parse(res);

        if (!data || !data.data || !data.data.length) {
            java.log("获取分类失败: " + res);
            java.toast("获取分类失败，请检查登录状态");
            return;
        }

        var excludeIds = { "-1": true, "-2": true, "-3": true };
        var classList = [];
        for (var i = 0; i < data.data.length; i++) {
            var item = data.data[i];
            var cid = String(item.classid);
            if (excludeIds[cid]) continue;
            classList.push({
                classId: cid,
                className: String(item.classname)
            });
        }

        if (classList.length == 0) {
            java.toast("暂无可用分类");
            return;
        }

        var config = getConfig.call(this);
        var savedId = String(config.type_id || "");

        var cardsHtml = "";
        for (var j = 0; j < classList.length; j++) {
            var c = classList[j];
            var selected = (String(c.classId) == savedId) ? " selected" : "";
            cardsHtml +=
                '<div class="class-card' + selected + '" data-id="' + c.classId + '" onclick="pick(this)">' +
                    '<div class="class-name">' + c.className + '</div>' +
                    '<div class="class-id">ID: ' + c.classId + '</div>' +
                '</div>';
        }

        var html = `<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1.0,maximum-scale=1.0,user-scalable=no">
