<style>
*{margin:0;padding:0;box-sizing:border-box;-webkit-tap-highlight-color:transparent}
body{font-family:-apple-system,BlinkMacSystemFont,'PingFang SC','Microsoft YaHei',sans-serif;background:#0a0a0f;background-image:radial-gradient(ellipse at 30% 20%, #2a1020 0%, #0a0e27 50%, #1a0d1a 100%);color:#e8e8f0;min-height:100vh;padding:20px}
.header{text-align:center;padding:10px 0 18px}
.header h1{font-size:1.3rem;font-weight:800;background:linear-gradient(135deg,#e8e8f0 40%,#c14a63);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text}
.header p{font-size:.72rem;color:#8888a0;margin-top:4px}
.current-bar{display:flex;align-items:center;gap:8px;padding:10px 14px;margin-bottom:16px;background:rgba(193,74,99,.1);border:1px solid rgba(193,74,99,.3);border-radius:10px;font-size:.74rem;color:rgba(255,255,255,.85)}
.current-bar strong{color:#fff}
