.class-card{position:relative;padding:16px 10px;border-radius:14px;background:rgba(255,255,255,.04);border:2px solid rgba(255,255,255,.08);cursor:pointer;transition:all .25s;text-align:center}
.class-card:hover{border-color:rgba(255,255,255,.2);background:rgba(255,255,255,.08)}
