.class-card.selected::after{content:'✓';position:absolute;top:6px;right:8px;width:18px;height:18px;border-radius:50%;background:#c14a63;color:#fff;font-size:11px;display:flex;align-items:center;justify-content:center}
.class-name{font-size:.8rem;font-weight:600;color:rgba(255,255,255,.9);word-break:break-all}
.class-id{font-size:.62rem;color:rgba(255,255,255,.4);margin-top:4px}
.tip{text-align:center;font-size:.68rem;color:rgba(255,255,255,.35);margin-top:20px}
</style>
</head>
