function pick(el){
    document.querySelectorAll('.class-card').forEach(function(c){c.classList.remove('selected');});
    el.classList.add('selected');
    document.getElementById('currentId').textContent = el.getAttribute('data-id');
    document.getElementById('result-output').textContent = el.getAttribute('data-id');
}
</script>
</body>
</html>`;

        var base64 = "data:text/html;base64," + java.base64Encode(html);
        var result = java.startBrowserAwait(base64, "晋江收藏分类", false);

        if (!result || !result.body()) {
            java.toast("已取消分类设置");
            return;
        }

        var bodyHtml = result.body();
        var match = bodyHtml.match(/<div id="result-output"[^>]*>([^<]*)<\/div>/);
        var newId = "";
        if (match && match[1]) {
            newId = match[1].trim();
        }

        if (!newId) {
            java.toast("未选择分类");
            return;
        }

        setConfig.call(this, 'type_id', String(newId));
        java.toast("\n已保存分类ID：" + newId);

    } catch (e) {
        java.log("获取书架分类失败: " + e);
        java.toast("\n获取书架分类失败");
    }
}

