            (historyHtml ? '<div class="section" style="padding:0"><div class="history-head" onclick="toggleLogs()"><h2><i class="fas fa-history"></i> 历史更新 <span>' + historyCountText + '</span></h2><button class="toggle"><span id="toggleText">展开历史</span><i class="fas fa-chevron-down" id="toggleIcon"></i></button></div><div class="history-body" id="logList">' + historyHtml + '</div></div>' : '') +
            '<p class="foot">' + (force ? '本次为强制更新，请更新后再使用书源' : '更新后返回书源即可生效') + '</p>' +
            '</section></div>' +
            '<script>' +
            'let logsCollapsed=true;' +
            'function toggleLogs(){logsCollapsed=!logsCollapsed;var l=document.getElementById("logList");var t=document.getElementById("toggleText");var i=document.getElementById("toggleIcon");' +
            'if(logsCollapsed){l.classList.remove("open");t.textContent="展开历史";i.className="fas fa-chevron-down";}else{l.classList.add("open");t.textContent="收起历史";i.className="fas fa-chevron-up";}}' +
            '</script></body></html>';

        if (downloadUrl) {
            try {
                java.startBrowserAwait('data:text/html;base64,' + java.base64Encode(bodyHtml), '书源更新', false);
            } catch (e) {
                java.toast('打开更新页失败：' + e);
            }
        } else {
            java.longToast('发现新版本：' + serverVer + '\n' + msg);
        }
        return;
    }

    if (cmp < 0) {
        java.longToast('非法版本\n本地版本：' + myLocalVer + '\n服务器版本：' + serverVer + '\n本地版本高于服务器版本，请检查书源来源是否被修改。');
        return;
    }
    java.toast('已是最新版本：' + myLocalVer);
}

