function LZ_saveRoad(u){
  var s=String(u||'').trim();
  if(s.length<6){ LZ_toast('✖ 发布页地址太短，未保存'); return 'fail'; }
  if(s.indexOf('http')!=0) s='https://'+s.replace(/^\/+/,'');
